2163	                let dead = match table.try_borrow_mut() {
2164	                    Ok(mut table) => Some(table.prune()),
2165	                    Err(_) => None,
2166	                };
2167	                let found = table.try_borrow().ok().and_then(|table| {
2168	                    let index = table.position(id)?;
2169	                    let (_, entry_kind, value) = &table.entries[index];
2170	                    let live =
2171	                        *entry_kind == kind && (dead.is_some() || registry().holds(id, kind));
2172	                    if live { read(value) } else { None }
2173	                });
2174	                drop(dead);
