    // `git_atomic_ssize` is `git_atomic64` in the bindings, as `AtomicSsize` is `Atomic64`.
    #[cfg(target_pointer_width = "64")]
    const _: fn(sys::git_atomic_ssize) -> sys::git_atomic64 = |ssize| ssize;

