        ///
        /// Two exclusive handles to one value cannot coexist:
        ///
        /// ```compile_fail,E0499
        /// use libgit2_crustify::libgit2::src::util::thread::Thread;
        ///
        /// let mut thread = Thread::default();
        /// let a = thread.as_mut();
        /// let b = thread.as_mut();
        /// let _ = (a, b);
        /// ```
