//! SCRATCH PROBE (batch-5), not to be committed.
#![allow(unsafe_code, missing_docs, clippy::all)]
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use std::thread;
use std::time::{Duration, Instant};

use libgit2_crustify::libgit2::src::util::thread::TlsKey;

unsafe extern "C" {
    fn fork() -> i32;
    fn exit(code: i32) -> !;
    fn waitpid(pid: i32, status: *mut i32, options: i32) -> i32;
    fn kill(pid: i32, sig: i32) -> i32;
}

#[test]
fn zz_probe_fork_child_exit() {
    let stop = Arc::new(AtomicBool::new(false));
    let s = Arc::clone(&stop);
    let spinner = thread::spawn(move || {
        while !s.load(Ordering::Relaxed) {
            let k = TlsKey::<u8>::new(None).unwrap();
            k.dispose().unwrap();
        }
    });
    let key = TlsKey::<u8>::new(None).unwrap();
    key.set(Some(1)).unwrap();
    let mut hung = 0;
    let forks = 200;
    for _ in 0..forks {
        let pid = unsafe { fork() };
        if pid == 0 {
            unsafe { exit(0) }
        }
        let start = Instant::now();
        let mut st = 0;
        loop {
            if unsafe { waitpid(pid, &mut st, 1) } == pid {
                break;
            }
            if start.elapsed() > Duration::from_secs(2) {
                hung += 1;
                unsafe { kill(pid, 9) };
                unsafe { waitpid(pid, &mut st, 0) };
                break;
            }
            thread::sleep(Duration::from_millis(1));
        }
    }
    stop.store(true, Ordering::Relaxed);
    spinner.join().unwrap();
    eprintln!("PROBE: {hung} of {forks} forked children hung in exit()");
}
EOF
